import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from './useAuth'; // Assuming you have a custom hook for auth
import './OrderHistory.css';

const OrderHistory = () => {
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const { user } = useAuth(); // Get user from your auth context

    useEffect(() => {
        if (!user) {
            setLoading(false);
            setError('You must be logged in to view your order history.');
            return;
        }

        const fetchOrders = async () => {
            console.log('user.id:', user.id);
            try {
                const response = await axios.get(`http://localhost:8082/api/orders/customer/${user.id}`);
                setOrders(response.data);
                setLoading(false);
            } catch (err) {
                setError('Failed to fetch orders. Please try again later.');
                setLoading(false);
            }
        };

        fetchOrders();
    }, [user]);

    if (loading) {
        return <div>Loading...</div>;
    }

    if (error) {
        return <div>{error}</div>;
    }

    return (
        <div className="order-history-container">
            <h2>Your Order History</h2>
            {orders.length === 0 ? (
                <p>You have no orders.</p>
            ) : (
                <table className="order-history-table">
                    <thead>
                        <tr>
                            <th>Order ID</th>
                            <th>Date</th>
                            <th>Total Price</th>
                            <th>Status</th>
                        </tr>
                    </thead>
                    <tbody>
                        {orders.map(order => (
                            <tr key={order.id}>
                                <td>{order.id}</td>
                                <td>{new Date(order.orderDate).toLocaleDateString()}</td>
                                <td>${order.totalPrice.toFixed(2)}</td>
                                <td>{order.status}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            )}
        </div>
    );
};

export default OrderHistory;
